      /\ s_fsize (stof f) mod 16 = 0 /\ 16 <= s_fsize (stof f)
      /\ (s_fsize (stof f) < 2^32 /\ 8 + 8 * Z.of_nat (saved_count (stof f)) <= s_fsize (stof f))
      /\ A + 1856 <= fr_sp f
      /\ bv_unsigned (fr_ra f) = s_ip (stof g)
      /\ cell8 M0 (fr_sp g - 8) (fr_ra f)
      /\ (forall k, (k < saved_count (stof f))%nat ->
             nth k (s_saved (stof f)) 0 = -16 - 8 * Z.of_nat k /\ cell8 M0 (fr_sp g - 16 - 8 * Z.of_nat k) (live g k))
      /\ (saved_count (stof f) <= 12)%nat
      /\ (forall k, (saved_count (stof f) <= k < 12)%nat -> live f k = live g k)
      /\ (0x131000 <= fr_sp f -> fdef M0 (fr_sp f) (s_fsize (stof f)))
  end.

